create table if not exists public.dreem_user_active_school(user_id uuid primary key references auth.users(id) on delete cascade,school_id uuid not null references public.schools(id) on delete cascade,selected_at timestamptz not null default now());alter table public.dreem_user_active_school enable row level security;revoke all on public.dreem_user_active_school from anon;grant select on public.dreem_user_active_school to authenticated;drop policy if exists "user reads active school context" on public.dreem_user_active_school;create policy "user reads active school context" on public.dreem_user_active_school for select to authenticated using(user_id=(select auth.uid()));
create or replace function public.dreem_list_my_school_contexts()returns table(school_id uuid,school_name text,role text)language sql security definer set search_path='' as $$select m.school_id,s.name,m.role from public.dreem_school_memberships m join public.schools s on s.id=m.school_id where m.profile_id=(select auth.uid())and m.status='approved' order by s.name;$$;revoke all on function public.dreem_list_my_school_contexts() from public;grant execute on function public.dreem_list_my_school_contexts() to authenticated;
create or replace function public.dreem_select_active_school(p_school_id uuid)returns table(school_id uuid,role text)language plpgsql security definer set search_path='' as $$declare v_role text;begin select m.role into v_role from public.dreem_school_memberships m where m.school_id=p_school_id and m.profile_id=(select auth.uid())and m.status='approved' limit 1;if v_role is null then raise exception 'That school is not an approved membership for this account';end if;insert into public.dreem_user_active_school(user_id,school_id,selected_at)values((select auth.uid()),p_school_id,now())on conflict(user_id)do update set school_id=excluded.school_id,selected_at=now();insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(p_school_id,(select auth.uid()),'school.context_selected','school',p_school_id,jsonb_build_object('role',v_role));return query select p_school_id,v_role;end;$$;revoke all on function public.dreem_select_active_school(uuid) from public;grant execute on function public.dreem_select_active_school(uuid) to authenticated;
create or replace function private.dreem_active_school_context()returns uuid language plpgsql security definer set search_path='' stable as $$declare v_user uuid:=(select auth.uid());v_school uuid;v_count integer;begin if v_user is null then return null;end if;select a.school_id into v_school from public.dreem_user_active_school a join public.dreem_school_memberships m on m.school_id=a.school_id and m.profile_id=a.user_id and m.status='approved' where a.user_id=v_user;if v_school is not null then return v_school;end if;select count(*),min(m.school_id)into v_count,v_school from public.dreem_school_memberships m where m.profile_id=v_user and m.status='approved';if v_count=1 then return v_school;end if;return null;end;$$;revoke all on function private.dreem_active_school_context() from public;grant execute on function private.dreem_active_school_context() to authenticated;
drop policy if exists "dreem_memberships_active_school_restrict" on public.dreem_school_memberships;create policy "dreem_memberships_active_school_restrict" on public.dreem_school_memberships as restrictive for select to authenticated using(school_id=private.dreem_active_school_context());